```tsx
// components/Hero.tsx
"use client";

import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";

gsap.registerPlugin(useGSAP);

type HeroProps = {
  title?: string;
  subtitle?: string;
};

export function Hero({
  title = "Ideas que dejan huella.",
  subtitle = "Diseñamos experiencias digitales precisas, memorables y construidas para mover tu negocio.",
}: HeroProps) {
  const heroRef = useRef<HTMLElement>(null);

  useGSAP(
    () => {
      const media = gsap.matchMedia();

      media.add("(prefers-reduced-motion: no-preference)", () => {
        gsap.to("[data-hero-reveal]", {
          autoAlpha: 1,
          y: 0,
          duration: 1,
          stagger: 0.14,
          ease: "power3.out",
        });
      });

      return () => media.revert();
    },
    { scope: heroRef },
  );

  return (
    <section
      ref={heroRef}
      aria-labelledby="hero-title"
      className="relative isolate flex min-h-[85svh] items-center overflow-hidden bg-[#f1eee7] px-6 py-24 text-[#171714] sm:px-10 lg:px-16"
    >
      <div
        aria-hidden="true"
        className="absolute inset-0 -z-10 opacity-45"
        style={{
          backgroundImage:
            "radial-gradient(circle at 82% 18%, rgba(201,73,43,.32), transparent 26%), radial-gradient(circle at 10% 85%, rgba(37,88,73,.2), transparent 28%)",
        }}
      />

      <div
        aria-hidden="true"
        className="absolute right-[8%] top-[12%] -z-10 h-64 w-64 rounded-full border border-[#171714]/15 sm:h-96 sm:w-96"
      />

      <div className="mx-auto w-full max-w-7xl">
        <div className="max-w-5xl">
          <p className="mb-7 flex items-center gap-3 text-xs font-semibold uppercase tracking-[0.24em] text-[#a63f28]">
            <span className="h-px w-8 bg-current" />
            Estudio digital independiente
          </p>

          <h1
            id="hero-title"
            data-hero-reveal
            className="invisible max-w-5xl translate-y-6 text-balance font-serif text-[clamp(3.5rem,10vw,9rem)] leading-[0.87] tracking-[-0.055em] opacity-0 motion-reduce:visible motion-reduce:translate-y-0 motion-reduce:opacity-100"
          >
            {title}
          </h1>

          <p
            data-hero-reveal
            className="invisible mt-9 max-w-2xl translate-y-6 text-pretty text-lg leading-relaxed text-[#171714]/65 opacity-0 motion-reduce:visible motion-reduce:translate-y-0 motion-reduce:opacity-100 sm:ml-[18%] sm:text-xl lg:text-2xl"
          >
            {subtitle}
          </p>
        </div>
      </div>
    </section>
  );
}
```

Uso desde una página del App Router:

```tsx
import { Hero } from "@/components/Hero";

export default function HomePage() {
  return (
    <main>
      <Hero
        title="Tu próxima gran idea empieza acá."
        subtitle="Creamos productos digitales con una dirección visual clara y una ejecución impecable."
      />
    </main>
  );
}
```

El estado inicial oculto y desplazado ahora existe en CSS desde el primer render, antes de que GSAP se inicialice, evitando el FOUC. GSAP anima hacia el estado visible y `motion-reduce` mantiene el contenido visible sin animación cuando corresponde.
